	sbom := &model.SBOM{ID: id, Components: []model.Component{}}
	if err := q.QueryRowContext(ctx,
		"SELECT artifact, version FROM sboms WHERE id = ?", id,
	).Scan(&sbom.Artifact, &sbom.Version); err != nil {
