package store

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"io"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
	_ "modernc.org/sqlite"
	sqlitedriver "modernc.org/sqlite"
)

// queryCounter is a database/sql/driver.Driver that wraps the real SQLite
// driver. It observes every statement that actually reaches the database: the
// tests count SELECT executions and returned rows at this boundary instead of
// trusting or mocking the store's internal functions, and can force a read
// failure on a chosen SELECT to exercise the 503 path.
type queryCounter struct {
	inner driver.Driver
	mu    sync.Mutex
	stats queryStats
	// failKind, when non-empty, makes the next SELECT of that kind fail.
	failKind string
}

type queryStats struct {
	selects      int
	rowsByKind   map[string]int
}

func (d *queryCounter) Open(name string) (driver.Conn, error) {
	raw, err := d.inner.Open(name)
	if err != nil {
		return nil, err
	}
	return &countingConn{Conn: raw, d: d}, nil
}

type countingConn struct {
	driver.Conn
	d *queryCounter
}

func (c *countingConn) Exec(query string, args []driver.Value) (driver.Result, error) {
	return c.Conn.(driver.Execer).Exec(query, args)
}

func (c *countingConn) Query(query string, args []driver.Value) (driver.Rows, error) {
	kind := selectKind(query)
	if kind != "" {
		c.d.mu.Lock()
		fail := c.d.failKind == kind
		c.d.mu.Unlock()
		if fail {
			return nil, errors.New("forced read failure from test driver")
		}
	}
	rows, err := c.Conn.(driver.Queryer).Query(query, args)
	if err != nil || kind == "" {
		return rows, err
	}
	c.d.mu.Lock()
	c.d.stats.selects++
	c.d.mu.Unlock()
	return &countingRows{Rows: rows, d: c.d, kind: kind}, nil
}

type countingRows struct {
	driver.Rows
	d    *queryCounter
	kind string
}

func (r *countingRows) Next(dest []driver.Value) error {
	err := r.Rows.Next(dest)
	if err == nil {
		r.d.mu.Lock()
		r.d.stats.rowsByKind[r.kind]++
		r.d.mu.Unlock()
	}
	return err
}

// selectKind classifies the store's read statements. Transaction control and
// DDL return the empty string and are never counted.
func selectKind(query string) string {
	s := strings.ToUpper(strings.TrimSpace(query))
	if !strings.HasPrefix(s, "SELECT") {
		return ""
	}
	switch {
	case strings.Contains(s, "COUNT(*)"):
		return "count"
	case strings.Contains(s, "FROM COMPONENTS C"):
		return "components"
	case strings.Contains(s, "FROM DEPENDENCIES D"):
		return "dependencies"
	default:
		return "sboms"
	}
}

var (
	registerCounterOnce sync.Once
	counter             *queryCounter
)

func openCountingStore(t *testing.T) (*Store, *queryCounter) {
	t.Helper()
	registerCounterOnce.Do(func() {
		counter = &queryCounter{
			inner: &sqlitedriver.Driver{},
			stats: queryStats{rowsByKind: map[string]int{}},
		}
		sql.Register("sqlite-counttest", counter)
	})
	counter.mu.Lock()
	counter.stats = queryStats{rowsByKind: map[string]int{}}
	counter.failKind = ""
	counter.mu.Unlock()

	st, err := open(filepath.Join(t.TempDir(), "counted.db"), "sqlite-counttest")
	if err != nil {
		t.Fatalf("open counting store: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return st, counter
}

func (d *queryCounter) snapshot() (selects int, rows map[string]int) {
	d.mu.Lock()
	defer d.mu.Unlock()
	rows = make(map[string]int, len(d.stats.rowsByKind))
	for k, v := range d.stats.rowsByKind {
		rows[k] = v
	}
	return d.stats.selects, rows
}

func registerManifest(t *testing.T, st *Store, artifact, version string, comps []model.Component) *model.SBOM {
	t.Helper()
	got, created, err := st.Register(context.Background(), &model.SBOM{
		Artifact: artifact, Version: version, Components: comps,
	})
	if err != nil {
		t.Fatalf("register %s@%s: %v", artifact, version, err)
	}
	if !created {
		t.Fatalf("register %s@%s: not created", artifact, version)
	}
	return got
}

func compsWithDeps(a, b string, aDeps []string) []model.Component {
	return []model.Component{
		{Coordinate: a, License: "L-" + a, Dependencies: aDeps},
		{Coordinate: b, License: "L-" + b, Dependencies: []string{}},
	}
}

// TestListUsesAtMostFourSelects proves the query budget against the real driver:
// one manifest or a full hundred both take four SELECTs (count, page rows, one
// batched components read, one batched dependencies read), and the two detail
// reads never return rows for anything outside the current page.
func TestListUsesAtMostFourSelects(t *testing.T) {
	ctx := context.Background()

	t.Run("one manifest", func(t *testing.T) {
		st, counted := openCountingStore(t)
		registerManifest(t, st, "app", "1", []model.Component{
			{Coordinate: "a", License: "A", Dependencies: []string{"b", "c"}},
			{Coordinate: "b", License: "B", Dependencies: []string{"c"}},
			{Coordinate: "c", License: "C", Dependencies: []string{}},
		})

		items, total, err := st.List(ctx, "app", 1, 20)
		if err != nil {
			t.Fatalf("list: %v", err)
		}
		selects, rows := counted.snapshot()
		if selects > 4 {
			t.Fatalf("SELECT count = %d, want at most 4", selects)
		}
		if selects != 4 {
			t.Fatalf("non-empty page ran %d SELECTs, want exactly 4", selects)
		}
		if total != 1 || len(items) != 1 {
			t.Fatalf("total/items = %d/%d, want 1/1", total, len(items))
		}
		if rows["sboms"] != 1 || rows["components"] != 3 || rows["dependencies"] != 3 || rows["count"] != 1 {
			t.Fatalf("unexpected row reads: %+v", rows)
		}
	})

	t.Run("hundred manifests", func(t *testing.T) {
		st, counted := openCountingStore(t)
		const n = 100
		for i := 0; i < n; i++ {
			registerManifest(t, st, "app", string(rune('0'+i/10))+string(rune('0'+i%10)),
				[]model.Component{
					{Coordinate: "a", License: "A", Dependencies: []string{"b"}},
					{Coordinate: "b", License: "B", Dependencies: []string{}},
				})
		}
		// Other artifact with the same coordinates: its detail rows must never
		// be read as part of an "app" page.
		registerManifest(t, st, "other", "1", []model.Component{
			{Coordinate: "a", License: "SECRET", Dependencies: []string{"b"}},
			{Coordinate: "b", License: "SECRET", Dependencies: []string{"a"}},
		})

		items, total, err := st.List(ctx, "app", 1, 100)
		if err != nil {
			t.Fatalf("list: %v", err)
		}
		selects, rows := counted.snapshot()
		if selects != 4 {
			t.Fatalf("100-item page ran %d SELECTs, want exactly 4", selects)
		}
		if total != n || len(items) != n {
			t.Fatalf("total/items = %d/%d, want %d/%d", total, len(items), n, n)
		}
		if rows["sboms"] != n || rows["components"] != 2*n || rows["dependencies"] != n {
			t.Fatalf("detail reads escaped the page or artifact: %+v", rows)
		}
		for _, item := range items {
			if item.Artifact != "app" {
				t.Fatalf("foreign manifest on page: %q", item.Artifact)
			}
			for _, c := range item.Components {
				if c.License == "SECRET" {
					t.Fatalf("component from another artifact leaked onto the page: %+v", c)
				}
			}
		}
	})

	t.Run("middle page", func(t *testing.T) {
		st, counted := openCountingStore(t)
		for i := 0; i < 5; i++ {
			registerManifest(t, st, "app", string(rune('0'+i)),
				compsWithDeps("a", "b", []string{"b"}))
		}

		items, total, err := st.List(ctx, "app", 2, 2)
		if err != nil {
			t.Fatalf("list: %v", err)
		}
		selects, rows := counted.snapshot()
		if selects != 4 {
			t.Fatalf("middle page ran %d SELECTs, want 4", selects)
		}
		if total != 5 || len(items) != 2 {
			t.Fatalf("total/items = %d/%d, want 5/2", total, len(items))
		}
		// Only the two manifests on this page may have their details read.
		if rows["components"] != 4 || rows["dependencies"] != 2 {
			t.Fatalf("detail reads escaped the current page: %+v", rows)
		}
	})

	t.Run("empty page skips detail reads", func(t *testing.T) {
		st, counted := openCountingStore(t)
		for _, kind := range []struct {
			name     string
			artifact string
			page     int
		}{
			{"unknown artifact", "ghost", 1},
			{"past last page", "app", 4},
		} {
			t.Run(kind.name, func(t *testing.T) {
				registerManifest(t, st, "app", "1", compsWithDeps("a", "b", nil))
				registerManifest(t, st, "app", "2", compsWithDeps("a", "b", nil))
				registerManifest(t, st, "app", "3", compsWithDeps("a", "b", nil))

				counted.mu.Lock()
				counted.stats = queryStats{rowsByKind: map[string]int{}}
				counted.mu.Unlock()

				items, total, err := st.List(ctx, kind.artifact, kind.page, 2)
				if err != nil {
					t.Fatalf("list: %v", err)
				}
				selects, rows := counted.snapshot()
				if selects > 4 {
					t.Fatalf("SELECT count = %d, want at most 4", selects)
				}
				// Count plus page scan only; IN-list detail queries must not run.
				if selects != 2 || rows["components"] != 0 || rows["dependencies"] != 0 {
					t.Fatalf("empty page ran %d selects with rows %+v, want 2 selects and no detail rows", selects, rows)
				}
				if items == nil || len(items) != 0 {
					t.Fatalf("items = %v, want non-nil empty slice", items)
				}
				if kind.name == "unknown artifact" && total != 0 {
					t.Fatalf("unknown artifact total = %d, want 0", total)
				}
				if kind.name == "past last page" && total != 3 {
					t.Fatalf("total = %d, want 3 preserved past last page", total)
				}
			})
		}
	})
}

// TestListReconstructsManifests verifies ordering, empty-array output, cycles
// and the complete contents of every manifest on a page.
func TestListReconstructsManifests(t *testing.T) {
	st, _ := openCountingStore(t)
	ctx := context.Background()

	// Empty manifest: no components at all.
	registerManifest(t, st, "app", "empty", []model.Component{})
	// Components without dependencies: dependencies must come back as an empty
	// array, not null.
	registerManifest(t, st, "app", "plain", []model.Component{
		{Coordinate: "z", License: "Z", Dependencies: []string{}},
		{Coordinate: "a", License: "A", Dependencies: []string{}},
	})
	// Legal dependency cycle a<->b must round-trip completely.
	registerManifest(t, st, "app", "cycle", []model.Component{
		{Coordinate: "a", License: "A", Dependencies: []string{"b"}},
		{Coordinate: "b", License: "B", Dependencies: []string{"a"}},
	})

	items, total, err := st.List(ctx, "app", 1, 20)
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if total != 3 || len(items) != 3 {
		t.Fatalf("total/items = %d/%d", total, len(items))
	}

	empty := items[0]
	if empty.Version != "empty" || empty.Components == nil || len(empty.Components) != 0 {
		t.Fatalf("empty manifest = %+v, want non-nil empty components", empty)
	}

	plain := items[1]
	if plain.Version != "plain" {
		t.Fatalf("items not ordered by id: %s", plain.Version)
	}
	if plain.Components[0].Coordinate != "a" || plain.Components[1].Coordinate != "z" {
		t.Fatalf("components not ordered by coordinate: %+v", plain.Components)
	}
	for _, c := range plain.Components {
		if c.Dependencies == nil || len(c.Dependencies) != 0 {
			t.Fatalf("empty dependencies = %v, want non-nil empty slice", c.Dependencies)
		}
	}

	cycle := items[2]
	deps := map[string][]string{}
	for _, c := range cycle.Components {
		deps[c.Coordinate] = c.Dependencies
	}
	if got := deps["a"]; len(got) != 1 || got[0] != "b" {
		t.Fatalf("cycle edge a-> = %v, want [b]", got)
	}
	if got := deps["b"]; len(got) != 1 || got[0] != "a" {
		t.Fatalf("cycle edge b-> = %v, want [a]", got)
	}
}

// TestListKeepsSameCoordinatesScopedPerVersion registers multiple versions
// (and another artifact) that share component coordinates but differ in
// licenses and dependency edges, then asserts every license and dependency
// stays with its own manifest.
func TestListKeepsSameCoordinatesScopedPerVersion(t *testing.T) {
	st, _ := openCountingStore(t)
	ctx := context.Background()

	registerManifest(t, st, "app", "1", []model.Component{
		{Coordinate: "lib", License: "Apache-2.0", Dependencies: []string{"util"}},
		{Coordinate: "util", License: "BSD-3-Clause", Dependencies: []string{}},
	})
	registerManifest(t, st, "app", "2", []model.Component{
		{Coordinate: "lib", License: "GPL-3.0", Dependencies: []string{}},
		{Coordinate: "util", License: "MIT", Dependencies: []string{"lib"}},
	})
	registerManifest(t, st, "app", "3", []model.Component{
		{Coordinate: "lib", License: "ISC", Dependencies: []string{"util"}},
		{Coordinate: "util", License: "Unlicense", Dependencies: []string{"lib"}},
	})
	registerManifest(t, st, "vendor", "1", []model.Component{
		{Coordinate: "lib", License: "PROPRIETARY", Dependencies: []string{}},
		{Coordinate: "util", License: "PROPRIETARY", Dependencies: []string{}},
	})

	items, total, err := st.List(ctx, "app", 1, 100)
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if total != 3 || len(items) != 3 {
		t.Fatalf("total/items = %d/%d, want 3/3", total, len(items))
	}

	want := []struct {
		version    string
		libLicense string
		libDeps    []string
		utilLicense string
		utilDeps   []string
	}{
		{"1", "Apache-2.0", []string{"util"}, "BSD-3-Clause", []string{}},
		{"2", "GPL-3.0", []string{}, "MIT", []string{"lib"}},
		{"3", "ISC", []string{"util"}, "Unlicense", []string{"lib"}},
	}
	for i, w := range want {
		got := items[i]
		if got.Version != w.version {
			t.Fatalf("item %d version = %q, want %q", i, got.Version, w.version)
		}
		byCoord := map[string]model.Component{}
		for _, c := range got.Components {
			byCoord[c.Coordinate] = c
		}
		lib, util := byCoord["lib"], byCoord["util"]
		if lib.License != w.libLicense || !sameStrings(lib.Dependencies, w.libDeps) {
			t.Fatalf("version %s lib = %+v, want license %q deps %v", w.version, lib, w.libLicense, w.libDeps)
		}
		if util.License != w.utilLicense || !sameStrings(util.Dependencies, w.utilDeps) {
			t.Fatalf("version %s util = %+v, want license %q deps %v", w.version, util, w.utilLicense, w.utilDeps)
		}
	}
}

func sameStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// TestListReadFailuresReturnUnavailable forces a failure at each of the four
// read steps. Every failure must surface model.ErrStorageUnavailable with no
// partial items.
func TestListReadFailuresReturnUnavailable(t *testing.T) {
	for _, kind := range []string{"count", "sboms", "components", "dependencies"} {
		t.Run(kind, func(t *testing.T) {
			st, counted := openCountingStore(t)
			registerManifest(t, st, "app", "1", []model.Component{
				{Coordinate: "a", License: "A", Dependencies: []string{"b"}},
				{Coordinate: "b", License: "B", Dependencies: []string{}},
			})

			counted.mu.Lock()
			counted.failKind = kind
			counted.mu.Unlock()

			items, _, err := st.List(context.Background(), "app", 1, 20)
			if err == nil {
				t.Fatalf("expected failure on %s read", kind)
			}
			if !errors.Is(err, model.ErrStorageUnavailable) {
				t.Fatalf("error = %v, want model.ErrStorageUnavailable", err)
			}
			if items != nil {
				t.Fatalf("items = %v, want nil on failed read", items)
			}
		})
	}
}

// TestListSnapshotStaysConsistentUnderConcurrentWriters hammers Register for
// the same artifact while pages are read. Every returned manifest must be
// complete (never a half-written registration) and the page must never exceed
// its size or contradict its total.
func TestListSnapshotStaysConsistentUnderConcurrentWriters(t *testing.T) {
	st, _ := openCountingStore(t)
	ctx := context.Background()
	for i := 0; i < 5; i++ {
		registerManifest(t, st, "app", string(rune('a'+i)),
			[]model.Component{
				{Coordinate: "a", License: "A", Dependencies: []string{"b"}},
				{Coordinate: "b", License: "B", Dependencies: []string{"a"}},
			})
	}

	var wg sync.WaitGroup
	stop := make(chan struct{})
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; ; i++ {
			select {
			case <-stop:
				return
			default:
			}
			_, _, _ = st.Register(ctx, &model.SBOM{
				Artifact: "app",
				Version:  "writer-" + string(rune('a'+i%26)) + string(rune('a'+(i/26)%26)) + string(rune('a'+(i/676)%26)),
				Components: []model.Component{
					{Coordinate: "a", License: "A", Dependencies: []string{"b"}},
					{Coordinate: "b", License: "B", Dependencies: []string{"a"}},
				},
			})
		}
	}()

	for i := 0; i < 50; i++ {
		items, total, err := st.List(ctx, "app", 1, 20)
		if err != nil {
			t.Fatalf("list during writes: %v", err)
		}
		if len(items) > 20 {
			t.Fatalf("page returned %d items, want at most 20", len(items))
		}
		if int64(len(items)) > total {
			t.Fatalf("items %d exceed total %d within one snapshot", len(items), total)
		}
		for _, item := range items {
			if item.Artifact != "app" || len(item.Components) != 2 {
				t.Fatalf("incomplete or foreign manifest visible: %+v", item)
			}
			deps := map[string][]string{}
			for _, c := range item.Components {
				deps[c.Coordinate] = c.Dependencies
			}
			if len(deps["a"]) != 1 || deps["a"][0] != "b" || len(deps["b"]) != 1 || deps["b"][0] != "a" {
				t.Fatalf("partially written manifest visible: %+v", item)
			}
		}
	}
	close(stop)
	wg.Wait()
}

