package store

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
	_ "modernc.org/sqlite"
	sqlitedriver "modernc.org/sqlite"
)

// queryCounter is a database/sql/driver.Driver wrapping the real SQLite
// driver. It observes every statement that actually reaches the database: the
// tests count SELECT executions and returned rows at this boundary instead of
// trusting or mocking the store's internal functions, and can force a read
// failure on a chosen SELECT kind to exercise the 503 path.
type queryCounter struct {
	inner driver.Driver
	mu    sync.Mutex
	stats queryStats
	// failKind, when non-empty, makes the next SELECT of that kind fail.
	failKind string
}

type queryStats struct {
	selects    int
	rowsByKind map[string]int
}

func (d *queryCounter) Open(name string) (driver.Conn, error) {
	raw, err := d.inner.Open(name)
	if err != nil {
		return nil, err
	}
	return &countingConn{Conn: raw, d: d}, nil
}

func (d *queryCounter) reset() {
	d.mu.Lock()
	d.stats = queryStats{rowsByKind: map[string]int{}}
	d.failKind = ""
	d.mu.Unlock()
}

func (d *queryCounter) failNext(kind string) {
	d.mu.Lock()
	d.failKind = kind
	d.mu.Unlock()
}

func (d *queryCounter) snapshot() (selects int, rows map[string]int) {
	d.mu.Lock()
	defer d.mu.Unlock()
	rows = make(map[string]int, len(d.stats.rowsByKind))
	for k, v := range d.stats.rowsByKind {
		rows[k] = v
	}
	return d.stats.selects, rows
}

// countingConn exposes the same legacy driver.Execer/driver.Queryer surface
// database/sql uses with the modernc driver; statements flow through Exec and
// Query where the counter lives.
type countingConn struct {
	driver.Conn
	d *queryCounter
}

func (c *countingConn) Exec(query string, args []driver.Value) (driver.Result, error) {
	return c.Conn.(driver.Execer).Exec(query, args)
}

func (c *countingConn) Query(query string, args []driver.Value) (driver.Rows, error) {
	kind := selectKind(query)
	if kind != "" {
		c.d.mu.Lock()
		fail := c.d.failKind == kind
		c.d.mu.Unlock()
		if fail {
			return nil, errors.New("forced read failure from test driver")
		}
	}
	rows, err := c.Conn.(driver.Queryer).Query(query, args)
	if err != nil || kind == "" {
		return rows, err
	}
	c.d.mu.Lock()
	c.d.stats.selects++
	c.d.mu.Unlock()
	return &countingRows{Rows: rows, d: c.d, kind: kind}, nil
}

type countingRows struct {
	driver.Rows
	d    *queryCounter
	kind string
}

func (r *countingRows) Next(dest []driver.Value) error {
	err := r.Rows.Next(dest)
	if err == nil {
		r.d.mu.Lock()
		r.d.stats.rowsByKind[r.kind]++
		r.d.mu.Unlock()
	}
	return err
}

// selectKind classifies the store's read statements. Transaction control, DDL
// and PRAGMAs return the empty string and are never counted.
func selectKind(query string) string {
	s := strings.ToUpper(strings.TrimSpace(query))
	if !strings.HasPrefix(s, "SELECT") {
		return ""
	}
	switch {
	case strings.Contains(s, "COUNT(*)"):
		return "count"
	case strings.Contains(s, "FROM COMPONENTS C"):
		return "components"
	case strings.Contains(s, "FROM DEPENDENCIES D"):
		return "dependencies"
	default:
		return "sboms"
	}
}

var (
	registerCounterOnce sync.Once
	counter             *queryCounter
)

func openCountingStore(t *testing.T) (*Store, *queryCounter) {
	t.Helper()
	registerCounterOnce.Do(func() {
		counter = &queryCounter{
			inner: &sqlitedriver.Driver{},
			stats: queryStats{rowsByKind: map[string]int{}},
		}
		sql.Register("sqlite-counttest", counter)
	})
	counter.reset()

	st, err := open(filepath.Join(t.TempDir(), "counted.db"), "sqlite-counttest")
	if err != nil {
		t.Fatalf("open counting store: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return st, counter
}

func registerManifest(t *testing.T, st *Store, artifact, version string, comps []model.Component) *model.SBOM {
	t.Helper()
	got, created, err := st.Register(context.Background(), &model.SBOM{
		Artifact: artifact, Version: version, Components: comps,
	})
	if err != nil {
		t.Fatalf("register %s@%s: %v", artifact, version, err)
	}
	if !created {
		t.Fatalf("register %s@%s: not created", artifact, version)
	}
	return got
}

func twoComponents(aDeps []string) []model.Component {
	return []model.Component{
		{Coordinate: "a", License: "L-a", Dependencies: aDeps},
		{Coordinate: "b", License: "L-b", Dependencies: []string{}},
	}
}

// TestListUsesAtMostFourSelects proves the query budget against the real
// driver: one manifest or a full hundred both take exactly four SELECTs
// (count, page rows, one batched components read, one batched dependencies
// read), and the two detail reads never return rows for anything outside the
// current page and requested artifact.
func TestListUsesAtMostFourSelects(t *testing.T) {
	ctx := context.Background()

	t.Run("one manifest", func(t *testing.T) {
		st, counted := openCountingStore(t)
		registerManifest(t, st, "app", "1", []model.Component{
			{Coordinate: "a", License: "A", Dependencies: []string{"b", "c"}},
			{Coordinate: "b", License: "B", Dependencies: []string{"c"}},
			{Coordinate: "c", License: "C", Dependencies: []string{}},
		})
