			t.Fatalf("unexpected row reads: %+v", rows)
		}
	})

	t.Run("hundred manifests", func(t *testing.T) {
		st, counted := openCountingStore(t)
		const n = 100
		for i := 0; i < n; i++ {
			version := string(rune('0'+i/10)) + string(rune('0'+i%10))
