package store

import (
	"database/sql"
	"database/sql/driver"
	"errors"
	"path/filepath"
	"strings"
	"sync"

	sqlitedriver "modernc.org/sqlite"
)

// This file is exported test support for packages that build a *Store through
// the real HTTP stack. It wraps the genuine SQLite driver (no mocks) so tests
// can count the statements a request actually issues and force a read failure
// deterministically. It is not part of the service's runtime API.

// StatementCounters summarizes the SELECTs observed by the counting driver.
type StatementCounters struct {
	// Selects is the total number of SELECT statements executed.
	Selects int
	// RowsByKind is the number of result rows returned, keyed by statement
	// kind: "count", "sboms", "components", "dependencies".
	RowsByKind map[string]int
}

// CountedStore is a Store whose traffic is counted at the driver boundary.
type CountedStore struct {
	*Store
	driver *queryCounter
}

// Counters returns a point-in-time copy of the statement counters.
func (s *CountedStore) Counters() StatementCounters {
	selects, rows := s.driver.snapshot()
	return StatementCounters{Selects: selects, RowsByKind: rows}
}

// ResetCounters clears the observed statement counters without touching data.
func (s *CountedStore) ResetCounters() { s.driver.reset() }

// FailNextRead makes the next SELECT of the given kind
// ("count"/"sboms"/"components"/"dependencies") fail at the driver, simulating
// a storage read error.
func (s *CountedStore) FailNextRead(kind string) { s.driver.failNext(kind) }

var (
	registerCountingOnce  sync.Once
	countingDriverName    = "sqlite-counttest"
	countingDriver        *queryCounter
)

// OpenCountedForTest opens a Store in dir backed by the real SQLite driver
// while counting every statement it issues.
func OpenCountedForTest(path string) (*CountedStore, error) {
	registerCountingOnce.Do(func() {
		countingDriver = &queryCounter{
			inner: &sqlitedriver.Driver{},
			stats: queryStats{rowsByKind: map[string]int{}},
		}
		sql.Register(countingDriverName, countingDriver)
	})
	countingDriver.reset()

	st, err := open(path, countingDriverName)
	if err != nil {
		return nil, err
	}
	return &CountedStore{Store: st, driver: countingDriver}, nil
}

// queryCounter is a database/sql/driver.Driver wrapping the real SQLite
// driver. It observes every statement that actually reaches the database.
type queryCounter struct {
	inner driver.Driver
	mu    sync.Mutex
	stats queryStats
	// failKind, when non-empty, makes the next SELECT of that kind fail.
	failKind string
}

type queryStats struct {
	selects    int
	rowsByKind map[string]int
}

func (d *queryCounter) Open(name string) (driver.Conn, error) {
	raw, err := d.inner.Open(name)
	if err != nil {
		return nil, err
	}
	return &countingConn{Conn: raw, d: d}, nil
}

func (d *queryCounter) reset() {
	d.mu.Lock()
	d.stats = queryStats{rowsByKind: map[string]int{}}
	d.failKind = ""
	d.mu.Unlock()
}

func (d *queryCounter) failNext(kind string) {
	d.mu.Lock()
	d.failKind = kind
	d.mu.Unlock()
}

func (d *queryCounter) snapshot() (selects int, rows map[string]int) {
	d.mu.Lock()
	defer d.mu.Unlock()
	rows = make(map[string]int, len(d.stats.rowsByKind))
	for k, v := range d.stats.rowsByKind {
		rows[k] = v
	}
	return d.stats.selects, rows
}

// countingConn exposes the legacy driver.Execer/driver.Queryer surface that
// database/sql uses with the modernc driver; statements flow through Exec and
// Query where the counter lives.
type countingConn struct {
	driver.Conn
	d *queryCounter
}

func (c *countingConn) Exec(query string, args []driver.Value) (driver.Result, error) {
	return c.Conn.(driver.Execer).Exec(query, args)
}

func (c *countingConn) Query(query string, args []driver.Value) (driver.Rows, error) {
	kind := selectKind(query)
	if kind != "" {
		c.d.mu.Lock()
		fail := c.d.failKind == kind
		c.d.mu.Unlock()
		if fail {
			return nil, errors.New("forced read failure from test driver")
		}
	}
	rows, err := c.Conn.(driver.Queryer).Query(query, args)
	if err != nil || kind == "" {
		return rows, err
	}
	c.d.mu.Lock()
	c.d.stats.selects++
	c.d.mu.Unlock()
	return &countingRows{Rows: rows, d: c.d, kind: kind}, nil
}

type countingRows struct {
	driver.Rows
	d    *queryCounter
	kind string
}

func (r *countingRows) Next(dest []driver.Value) error {
	err := r.Rows.Next(dest)
	if err == nil {
		r.d.mu.Lock()
		r.d.stats.rowsByKind[r.kind]++
		r.d.mu.Unlock()
	}
	return err
}

// selectKind classifies the store's read statements. Transaction control, DDL
// and PRAGMAs return the empty string and are never counted.
func selectKind(query string) string {
	s := strings.ToUpper(strings.TrimSpace(query))
	if !strings.HasPrefix(s, "SELECT") {
		return ""
	}
	switch {
	case strings.Contains(s, "COUNT(*)"):
		return "count"
	case strings.Contains(s, "FROM COMPONENTS C"):
		return "components"
	case strings.Contains(s, "FROM DEPENDENCIES D"):
		return "dependencies"
	default:
		return "sboms"
	}
}

